<script setup lang="ts">
import { Head, Link, useForm, router } from '@inertiajs/vue3';
import { watch, ref } from 'vue';
import AthletePicker from '../../Components/AthletePicker.vue';
import RolePermissions from '../../Components/RolePermissions.vue';
import AppLayout from '../../Layouts/AppLayout.vue';
interface AccessRole { id:number; name:string; description:string|null; permissions:string[]; is_default:boolean }
interface Athlete { id:number; first_name:string; last_name:string; email?:string }
interface Race { id:number; name:string; event_date:string }
interface User { id:number; name:string; email:string; role:'admin'|'organizer'|'athlete'; access_role?:AccessRole; is_active:boolean;force_password_change:boolean;invitation_sent_at?:string; athlete_id?:number; athlete?:Athlete; races:Race[] }
const props = defineProps<{ accessRoles:AccessRole[];  users:{data:User[];current_page:number;last_page:number;prev_page_url:string|null;next_page_url:string|null;total:number}; filters:{q:string}; races:Race[]; mailConfigured:boolean }>();
const search=ref(props.filters.q);
const searchUsers=()=>router.get('/users',{q:search.value},{preserveState:true,preserveScroll:true});
const form = useForm({name:'',email:'',password:'',delivery:props.mailConfigured?'email':'manual',role:'organizer',access_role_id:null as number|null,athlete_id:null as number|null,race_ids:[] as number[]});
watch(() => form.role, role => { if(role!=='athlete') form.athlete_id=null; if(role!=='organizer') {form.race_ids=[];form.access_role_id=null;} });
const submit = () => form.post('/users',{preserveScroll:true,onSuccess:()=>{form.reset();form.delivery=props.mailConfigured?'email':'manual';}});

</script>
<template><Head title="Users"/><AppLayout title="Users & access"><p class="mb-5 muted">Create accounts or edit a user’s details, role, race access and active status.</p><div class="grid gap-5 xl:grid-cols-[1fr_420px]"><section class="panel overflow-hidden"><div class="border-b border-outline p-4 font-bold">Accounts · {{ users.total }}</div><form @submit.prevent="searchUsers" class="flex gap-2 p-4"><input v-model="search" class="field" aria-label="Search accounts" placeholder="Name or email"><button class="btn-secondary">Search</button></form><div class="divide-y divide-outline"><div v-for="user in users.data" :key="user.id" class="flex flex-col items-start gap-3 p-4 sm:flex-row"><div class="min-w-0 flex-1"><div class="flex flex-wrap items-center gap-2"><span class="font-semibold">{{ user.name }}</span><span class="badge">{{ user.role==='admin'?'Organizer (admin)':user.role==='athlete'?'Athlete':user.access_role?.name??'Official' }}</span><span v-if="!user.is_active" class="badge !border-red-500/30 !text-error">disabled</span></div><div class="muted text-sm">{{ user.email }}</div><div class="mt-1 text-xs muted">{{ user.force_password_change ? (user.invitation_sent_at?'Invitation sent · password setup pending':'Password setup pending') : 'Password set' }}</div><div v-if="user.athlete" class="mt-1 text-xs text-muted">Athlete: {{ user.athlete.first_name }} {{ user.athlete.last_name }}</div><div v-if="user.races?.length" class="mt-1 text-xs text-muted">Races: {{ user.races.map(r=>r.name).join(', ') }}</div></div><Link :href="`/users/${user.id}/edit`" class="btn-secondary !min-h-11 !px-3 text-sm">Edit user</Link></div></div><nav aria-label="Account pages" class="flex flex-wrap items-center gap-3 p-4"><Link v-if="users.prev_page_url" :href="users.prev_page_url" class="btn-secondary" preserve-state>Previous</Link><span>Page {{ users.current_page }} of {{ users.last_page }}</span><Link v-if="users.next_page_url" :href="users.next_page_url" class="btn-secondary" preserve-state>Next</Link></nav></section><form class="panel-pad h-fit" @submit.prevent="submit"><h2 class="mb-4 text-lg font-bold">Create account</h2><div class="space-y-3"><div><label class="label" for="create-name">Name</label><input id="create-name" v-model="form.name" class="field" required></div><div><label class="label" for="create-email">Email</label><input id="create-email" v-model="form.email" type="email" class="field" required></div><div><label class="label" for="delivery">Account invitation</label><select id="delivery" v-model="form.delivery" class="field"><option value="email" :disabled="!mailConfigured">Email a password setup link</option><option value="manual">Share a temporary password myself</option></select><p class="mt-2 text-sm muted">{{ mailConfigured ? 'Email invitations contain a single-use link to choose a password.' : 'Email is not connected yet. Ask the site owner to configure email sending. Until then, share a temporary password privately.' }}</p></div><div v-if="form.delivery==='manual'"><label class="label" for="create-password">Temporary password</label><input id="create-password" v-model="form.password" type="password" class="field" minlength="12" required><p class="mt-1 text-xs muted">At least 12 characters. The user must change it before accessing the app.</p></div><div><label class="label" for="create-role">Role</label><select id="create-role" v-model="form.role" class="field"><option value="organizer">Official</option><option value="athlete">Athlete</option><option value="admin">Organizer (admin)</option></select></div><div v-if="form.role==='organizer'"><label for="access-role" class="label">Official role</label><select id="access-role" v-model="form.access_role_id" class="field"><option :value="null">Official (default)</option><option v-for="accessRole in accessRoles.filter(r=>!r.is_default)" :key="accessRole.id" :value="accessRole.id">{{ accessRole.name }}</option></select><p class="mt-2 text-sm muted">{{ (form.access_role_id?accessRoles.find(r=>r.id===form.access_role_id):accessRoles.find(r=>r.is_default))?.description }}</p><Link href="/admin/roles" class="mt-2 inline-block text-sm text-accent underline">Manage roles & permissions</Link></div><RolePermissions :role="form.role"/><AthletePicker v-if="form.role==='athlete'" v-model="form.athlete_id"/><div v-if="form.role==='organizer'"><label class="label">Race access</label><div class="max-h-48 space-y-2 overflow-auto rounded-xl border border-outline p-3"><label v-for="race in races" :key="race.id" class="flex gap-2 text-sm"><input v-model="form.race_ids" type="checkbox" :value="race.id"> <span>{{ race.name }}</span></label></div></div></div><p v-if="Object.keys(form.errors).length" class="mt-3 text-sm text-error">{{ Object.values(form.errors)[0] }}</p><button class="btn-primary mt-5 w-full" :disabled="form.processing">Create account</button></form></div></AppLayout></template>
